style.css:
@-moz-document domain("roblox.com") {
@font-face {
        font-family: "Shag Lounge";
        src: url("https://cdn.jsdelivr.net/gh/Kaiser9820/shag-lounge-woff2-api@main/Shag-Lounge.woff") format("woff");
        font-display: swap;
    }

    html,
    body,
    *,
    *::before,
    *::after,
    button,
    input,
    textarea,
    select,
    option {
        font-family: "Shag Lounge" !important;
    }

    [class*="font"],
    [class*="text"],
    [style*="Builder Sans"],
    [style*="BuilderSans"] {
        font-family: "Shag Lounge" !important;
    }
}
